<?php if($tab==='categories'):?><h2>Catalog departments</h2><p class="catalog-note">Category names, descriptions and ordering are stored in the database.</p><?php foreach(array_merge($admin['categories'],[['id'=>'','name'=>'','slug'=>'','description'=>'','position'=>0]]) as $c):?><details class="admin-record"><summary><strong><?=ui_e($c['name']?:'Add a department')?></strong><?=ui_icon('plus')?></summary><?php ui_form_start('/api/admin/categories','','/admin?tab=categories');?><input type="hidden" name="id" value="<?=ui_e($c['id'])?>"><?php ui_input('name','Department name','text',true,$c['name']);ui_input('slug','URL slug','text',true,$c['slug']);ui_input('description','Description','text',false,$c['description']);ui_input('position','Sort position','number',true,(string)$c['position']);?><button class="button primary">Save department</button></form></details><?php endforeach;?>
<?php elseif($tab==='coupons'):?><h2>Promotion codes</h2><p class="catalog-note">Retail promotions are validated by the server. They cannot be combined with dealer prices.</p><?php foreach(array_merge($admin['coupons'],[['code'=>'','percent'=>10,'expires_at'=>'','active'=>1]]) as $c):?><details class="admin-record"><summary><strong><?=ui_e($c['code']?:'Create a promotion')?></strong><span><?=$c['code']?(int)$c['percent'].'%':''?></span></summary><?php ui_form_start('/api/admin/coupons','','/admin?tab=coupons');ui_input('code','Promotion code','text',true,$c['code']);ui_input('percent','Discount percentage','number',true,(string)$c['percent']);ui_input('expires_at','Expiry date / time (UTC)','datetime-local',true,$c['expires_at']?substr($c['expires_at'],0,16):'');?><label class="consent-check"><input type="checkbox" name="active" <?=$c['active']?'checked':''?>>Active</label><button class="button primary">Save promotion</button></form></details><?php endforeach;?>
<?php elseif($tab==='variants'):?><h2>Configurations & pricing</h2><p class="catalog-note">Each configuration has its own SKU, exact price and stock. Dealer prices are never accepted from the shopping browser.</p><form action="/admin" class="sort-form"><input type="hidden" name="tab" value="variants"><label class="field"><span>Choose a product</span><select name="product" data-autosubmit><option value="">Select product</option><?php foreach($admin['products'] as $p):?><option value="<?=ui_e($p['slug'])?>" <?=($_GET['product']??'')===$p['slug']?'selected':''?>><?=ui_e($p['name'])?></option><?php endforeach;?></select></label><noscript><button>Choose product</button></noscript></form><?php $vp=isset($_GET['product'])?$store->product((string)$_GET['product']):null;if($vp):foreach(array_merge($vp['variants'],[['variant_id'=>'','variant_label'=>'','sku'=>'','price_cents'=>0,'stock'=>0]]) as $v):?><details class="admin-record"><summary><strong><?=ui_e($v['variant_label']?:'Add a configuration')?></strong><span><?=$v['variant_id']?ui_money($v['price_cents']):''?></span></summary><?php $raw=$v['variant_id']?$store->db->one('SELECT dealer_price_cents,attributes FROM product_variants WHERE id=?',[$v['variant_id']]):null;ui_form_start('/api/admin/variants','','/admin?tab=variants&product='.rawurlencode($vp['slug']));?><input type="hidden" name="id" value="<?=ui_e($v['variant_id'])?>"><input type="hidden" name="product_id" value="<?=(int)$vp['id']?>"><?php ui_input('label','Configuration name','text',true,$v['variant_label']);ui_input('sku','Verified merchant SKU','text',true,$v['sku']);?><div class="form-grid"><?php ui_input('price_cents','Retail price (integer cents)','number',true,(string)$v['price_cents']);ui_input('dealer_price_cents','Dealer price (integer cents, optional)','number',false,(string)($raw['dealer_price_cents']??''));ui_input('stock','Inventory quantity','number',true,(string)$v['stock']);?></div><label class="field"><span>Configuration attributes (JSON object)</span><textarea name="attributes" rows="3"><?=ui_e($raw['attributes']??'{}')?></textarea></label><button class="button primary">Save configuration</button></form></details><?php endforeach;endif;endif;?>
